//! Timed component experiments using frozen real library implementations.
use crate::{packet::{PacketPool,PacketQueue},performance::{Options,IoCounters},stream::Receive,session::{Session,Output}};
use std::{net::UdpSocket,os::fd::AsRawFd,time::{Duration,Instant,SystemTime,UNIX_EPOCH}};
fn cpu()->f64 {let mut t:libc::timespec=unsafe{std::mem::zeroed()};assert_eq!(unsafe{libc::clock_gettime(libc::CLOCK_THREAD_CPUTIME_ID,&mut t)},0);t.tv_sec as f64+t.tv_nsec as f64/1e9}
fn emit(v:serde_json::Value){println!("DECISION_JSON {}",v);}
fn sockets(mode:&str,size:usize,round:usize,gso:bool,gro:bool,buffers:usize){
    // Separate process invocation avoids process-global benchmark settings racing.
    unsafe {std::env::set_var("BENCH_GSO",if gso{"1"}else{"0"});std::env::set_var("BENCH_GRO",if gro{"1"}else{"0"});std::env::set_var("BENCH_BUFFERS",buffers.to_string());std::env::set_var("BENCH_SINGLE",if mode=="single"{"1"}else{"0"});}
    let a=UdpSocket::bind("127.0.0.1:0").unwrap();let b=UdpSocket::bind("127.0.0.1:0").unwrap();a.connect(b.local_addr().unwrap()).unwrap();b.connect(a.local_addr().unwrap()).unwrap();a.set_nonblocking(true).unwrap();b.set_nonblocking(true).unwrap();
    for s in [&a,&b] {let n:libc::c_int=1024*1024;unsafe{libc::setsockopt(s.as_raw_fd(),libc::SOL_SOCKET,libc::SO_RCVBUF,(&n as *const libc::c_int).cast(),4);}}
    let mut o=Options::parse("batch,in-place,compact").unwrap();o.udp_batch_size=if mode=="single"{1}else{16};o.udp_offload=gso||gro;
    let mut tx=crate::linux_batch::Batch::new(&a,o);let mut rx=crate::linux_batch::Batch::new(&b,o);
    let mut ur=if mode.starts_with("uring"){Some(crate::uring_rx::Receiver::new(&b,16).expect("requested io_uring must run"))}else{None};
    let mut counts=IoCounters::default();let mut pool=PacketPool::new(96,65535).unwrap();let mut out=pool.take().unwrap();let mut q=PacketQueue::new(64).unwrap();
    let packets=if size==64 {262144}else{52428800/size/16*16};let deadline=Instant::now()+Duration::from_secs(30);let c=cpu();let start=Instant::now();let mut received=0usize;
    for base in (0..packets).step_by(16){
        for seq in base..base+16 {let mut p=pool.take().unwrap();p.writable()[..size].fill(0x5a);p.writable()[..8].copy_from_slice(&(seq as u64).to_le_bytes());p.set_len(size).unwrap();q.push(p).ok().unwrap();}
        while tx.flush(&a,&mut q,&mut pool).unwrap(){assert!(Instant::now()<deadline);}
        while received<base+16 {let r=if let Some(u)=&mut ur {u.receive(&b,&mut out,&mut counts).unwrap()}else{rx.receive(&b,&mut out,&mut pool).unwrap()};match r {Receive::Packet=>{assert_eq!(out.data().len(),size);assert_eq!(u64::from_le_bytes(out.data()[..8].try_into().unwrap()),received as u64);assert!(out.data()[8..].iter().all(|b|*b==0x5a));received+=1;},_=>{assert!(Instant::now()<deadline,"UDP receive timeout {received}");std::hint::spin_loop();}}}
    }
    let seconds=start.elapsed().as_secs_f64();let cc=cpu()-c;let rc=if ur.is_some(){counts}else{rx.counters};
    if gso {assert!(tx.counters.gso_datagrams>0,"GSO requested but not exercised");}else{assert_eq!(tx.counters.gso_datagrams,0);}
    // GRO is only guaranteed in this fixture when sending actual segmented aggregates.
    if gso&&gro {assert!(rc.gro_datagrams>0,"GRO requested but not exercised");}
    assert_eq!(tx.counters.kernel_fallbacks+rc.kernel_fallbacks,0,"no silent fallback");
    if ur.is_some(){assert!(rc.io_uring_completions>0);}
    emit(serde_json::json!({"test":"udp-socket-component","mode":mode,"size":size,"round":round,"gso":gso,"gro":gro,"buffers":buffers,"bytes":received*size,"seconds":seconds,"Mbps":received as f64*size as f64*8.0/seconds/1e6,"thread_cpu_ns_per_byte":cc*1e9/(received*size) as f64,"tx":tx.counters,"rx":rc,"submissions":ur.as_ref().map(|u|u.submissions),"scope":"same-thread controlled loopback send+receive, real mmsg/RecvMsgMulti; no WG/TUN; not VPN throughput"}));
}
fn pair()->(Session,Session){let w=SystemTime::now().duration_since(UNIX_EPOCH).unwrap();let mut a=Session::new([7;32],Session::public_key([9;32]),None,Duration::ZERO,w).unwrap();let mut b=Session::new([9;32],Session::public_key([7;32]),None,Duration::ZERO,w).unwrap();let mut x=[0u8;2048];let mut y=[0u8;2048];let Output::Network(n)=a.initiate(&mut x).unwrap() else{panic!()};let Output::Network(n)=b.decrypt(&x[..n],&mut y).unwrap()else{panic!()};let Output::Network(n)=a.decrypt(&y[..n],&mut x).unwrap()else{panic!()};b.decrypt(&x[..n],&mut y).unwrap();while let Output::Network(n)=a.drain(&mut x).unwrap(){b.decrypt(&x[..n],&mut y).unwrap();}(a,b)}
fn crypto(mode:&str,size:usize,n:usize)->(f64,f64){let(mut a,mut b)=pair();let mut ip=vec![0x5a;size];ip[0]=0x45;ip[2..4].copy_from_slice(&(size as u16).to_be_bytes());ip[12..16].copy_from_slice(&[10,2,0,2]);ip[16..20].copy_from_slice(&[10,2,0,3]);let mut wire=vec![0u8;size+256];let mut clear=vec![0;size+256];wire[16..16+size].copy_from_slice(&ip);let c=cpu();let start=Instant::now();for _ in 0..n {if mode=="inplace" {let Output::Network(k)=a.encrypt_in_place(&mut wire,size).unwrap()else{panic!()};let Output::Tunnel(m)=b.decrypt_data_in_place(&mut wire[..k]).unwrap()else{panic!()};assert_eq!(m,size);assert_eq!(&wire[16..16+size],&ip);}else{let Output::Network(k)=a.encrypt(&ip,&mut wire).unwrap()else{panic!()};let Output::Tunnel(m)=b.decrypt(&wire[..k],&mut clear).unwrap()else{panic!()};assert_eq!(&clear[..m],&ip);}}(start.elapsed().as_secs_f64(),cpu()-c)}
fn cpus(){for round in 0..6 {for size in [64,1280] {for mode in if round%2==0 {["copy","inplace"]}else{["inplace","copy"]}{let n=100000;let(s,c)=crypto(mode,size,n);emit(serde_json::json!({"test":"crypto-roundtrip-component","mode":mode,"size":size,"round":round,"bytes":n*size,"seconds":s,"Mbps":n as f64*size as f64*8.0/s/1e6,"thread_cpu_ns_per_byte":c*1e9/(n*size)as f64,"scope":"real established Session roundtrip incl exact-payload validation; excludes TLS/TUN/rekey"}));}}
    for compact in [false,true] {let mut p=if compact{PacketPool::compact(132,2048,65535).unwrap()}else{PacketPool::new(132,65535).unwrap()};let reserved=p.reserved_bytes();let c=cpu();let s=Instant::now();for _ in 0..100000{let mut x=p.take().unwrap();x.writable()[..1280].fill(0x5a);x.set_len(1280).unwrap();p.recycle(x).unwrap();}emit(serde_json::json!({"test":"packet-pool-component","compact":compact,"round":round,"reserved_bytes":reserved,"seconds":s.elapsed().as_secs_f64(),"thread_cpu_seconds":cpu()-c,"scope":"pool take/write/recycle only; reservation is not RSS"}));}}
    for workers in [1,2,4] {let s=Instant::now();let handles:Vec<_>=(0..workers).map(|_|std::thread::spawn(move||crypto("inplace",1280,200000/workers))).collect();let c:f64=handles.into_iter().map(|h|h.join().unwrap().1).sum();emit(serde_json::json!({"test":"independent-session-worker-scaling","workers":workers,"bytes":200000*1280,"seconds":s.elapsed().as_secs_f64(),"summed_thread_cpu_seconds":c,"scope":"one separate Session pair per thread; NOT parallel crypto within one tunnel; not production worker implementation"}));}
}
fn tun(){use std::{fs::File,io::Read,process::Command};let ip=|a:&[&str]|assert!(Command::new("ip").args(a).status().unwrap().success());ip(&["link","set","lo","up"]);for round in 0..4 {for off in if round%2==0 {[false,true]}else{[true,false]} {let mut f=File::options().read(true).write(true).open("/dev/net/tun").unwrap();let mut req=[0u8;40];req[..4].copy_from_slice(b"pn30");let flags=libc::IFF_TUN|libc::IFF_NO_PI|if off{libc::IFF_VNET_HDR}else{0};req[16..18].copy_from_slice(&(flags as i16).to_ne_bytes());assert_eq!(unsafe{libc::ioctl(f.as_raw_fd(),libc::TUNSETIFF,req.as_mut_ptr())},0);if off{let n:libc::c_int=10;assert_eq!(unsafe{libc::ioctl(f.as_raw_fd(),libc::TUNSETVNETHDRSZ,&n)},0);assert_eq!(unsafe{libc::ioctl(f.as_raw_fd(),libc::TUNSETOFFLOAD,libc::TUN_F_CSUM|libc::TUN_F_TSO4|libc::TUN_F_TSO6|libc::TUN_F_USO4|libc::TUN_F_USO6)},0);}
ip(&["addr","add","10.2.0.2/32","dev","pn30"]);ip(&["link","set","pn30","mtu","1500","up"]);ip(&["route","add","10.2.0.3/32","dev","pn30"]);let s=UdpSocket::bind("10.2.0.2:0").unwrap();s.connect("10.2.0.3:9000").unwrap();if off {let seg:libc::c_int=1280;assert_eq!(unsafe{libc::setsockopt(s.as_raw_fd(),libc::SOL_UDP,libc::UDP_SEGMENT,(&seg as *const libc::c_int).cast(),4)},0);}
let body=vec![0x5a;1280*16];let mut out=vec![0;65535];let mut adapter=crate::tun_offload::Offload::for_file(&f).unwrap();let count=65536usize;let c=cpu();let start=Instant::now();for _ in 0..count/16 {if off{s.send(&body).unwrap();}else{for _ in 0..16{s.send(&body[..1280]).unwrap();}}for _ in 0..16 {let n=if let Some(a)=&mut adapter {a.read(&f,&mut out).unwrap()}else{f.read(&mut out).unwrap()};assert_eq!(n,1308);assert!(out[28..n].iter().all(|b|*b==0x5a));}}
emit(serde_json::json!({"test":"real-tun-boundary-component","offload":off,"round":round,"bytes":count*1280,"seconds":start.elapsed().as_secs_f64(),"thread_cpu_seconds":cpu()-c,"tun_read_records":adapter.as_ref().map(|a|a.read_records).unwrap_or(count as u64),"application_sends":if off{count/16}else{count},"scope":"application UDP send through actual TUN and original software segmentation; includes generator; no WG/TLS, not complete VPN throughput"}));drop(f);}}
}
pub fn run(){let args:Vec<_>=std::env::args().collect();emit(serde_json::json!({"test":"environment","kernel":std::fs::read_to_string("/proc/sys/kernel/osrelease").unwrap(),"architecture":std::env::consts::ARCH,"source":"83f0252 plus published experiment patch","scope":"component experiment, not final release acceptance"}));if args.get(1).map(String::as_str)==Some("--cpu"){cpus();return;}if args.get(1).map(String::as_str)==Some("--tun"){tun();return;}if args.get(1).map(String::as_str)==Some("--udp"){sockets(&args[2],args[3].parse().unwrap(),args[4].parse().unwrap(),args[5]=="1",args[6]=="1",args[7].parse().unwrap());return;}
    for round in 0..4 {for size in [64,1280] {let mut cases=vec![("single",false,false,16),("batch",false,false,16),("batch",true,false,16),("batch",false,true,16),("batch",true,true,16),("uring16",false,false,16),("uring128",false,false,128),("uring128",true,false,128),("uring128",false,true,128),("uring128",true,true,128)];if round%2==1{cases.reverse();}for(mode,gso,gro,buffers)in cases{sockets(mode,size,round,gso,gro,buffers);}}}
}
